const primaryCommand = command => Array.isArray(command) ? (command[0] || 'menu') : String(command || 'menu').split(/[ ,]/)[0]
const keyFor = (material, slot, items) => { const base=(material||'item').toLowerCase()+'_'+slot;let key=base,n=2;while(items[key])key=base+'_'+n++;return key }
function starter(){const c=createDefaultConfig();c.items={server_info:{material:'BOOK',slot:10,display_name:'&e&lServer Information',lore:['&7Learn more about this server.','','&eClick to view!'],left_click_commands:['[message] &eWelcome to the server!']},rewards:{material:'DIAMOND',slot:13,display_name:'&b&lDaily Rewards',lore:['&7Claim your daily reward.','&7Come back every day!'],left_click_commands:['[message] &aReward claimed!']},shop:{material:'EMERALD',slot:16,display_name:'&a&lServer Shop',lore:['&7Browse the server shop.'],left_click_commands:['[openguimenu] shop']}};return c}

const PREVIEW_CLICK_TYPES = [
 {id:'left',label:'Left click',field:'left_click_commands'},
 {id:'right',label:'Right click',field:'right_click_commands'},
 {id:'shift_left',label:'Shift + left',field:'shift_left_click_commands'},
 {id:'shift_right',label:'Shift + right',field:'shift_right_click_commands'},
 {id:'middle',label:'Middle click',field:'middle_click_commands'}
]
const getPreviewActions = (item, clickType) => {
 if (!item) return []
 const field = PREVIEW_CLICK_TYPES.find(type=>type.id===clickType)?.field
 return [...(item.click_commands||[]), ...(field ? item[field]||[] : [])].filter(Boolean).map(String)
}
const describePreviewAction = raw => {
 const match=String(raw).trim().match(/^\[([^\]]+)\]\s*(.*)$/)
 if(!match)return {kind:'Action',detail:String(raw).trim(),raw}
 const type=match[1].toLowerCase(),value=match[2].trim()
 if(type==='message'||type==='broadcast')return {kind:type==='message'?'Player message':'Broadcast',message:value,raw}
 if(type==='player')return {kind:'Player command',command:value?'/'+value:'(empty command)',executor:'The player',raw}
 if(type==='console')return {kind:'Console command',command:value||'(empty command)',executor:'The server console',raw}
 if(type==='openguimenu')return {kind:'Open menu',detail:value||'(menu not specified)',raw}
 if(type==='close')return {kind:'Close menu',detail:'Closes the inventory menu',raw}
 if(type==='sound')return {kind:'Play sound',detail:value||'(sound not specified)',raw}
 if(type==='connect')return {kind:'Connect server',detail:value||'(server not specified)',raw}
 if(type==='refresh')return {kind:'Refresh menu',detail:'Refreshes the open menu',raw}
 return {kind:'DeluxeMenus action · '+type,detail:value||'No extra arguments',raw}
}

const buildPreviewChat = (item, clickType) => {
 const actions=getPreviewActions(item,clickType)
 const name=String(item?.display_name||ITEM_BY_NAME[String(item?.material||'').toUpperCase()]?.displayName||item?.material||'Item')
 const lines=[{kind:'menu',text:'§a[Menu] §fClicked: '+name}]
 if(!actions.length) lines.push({kind:'system',text:'§7[Preview] §fNo actions are configured for this click.'})
 actions.forEach(raw=>{
  const action=describePreviewAction(raw)
  if(action.message!==undefined) lines.push({kind:'message',text:action.message})
  else if(action.command) lines.push({kind:'command',text:action.executor==='The player'?'§7[Player] §fWould run: §e/'+(action.command.startsWith('/')?action.command.slice(1):action.command):'§d[Console] §fWould execute: §e'+action.command})
  else if(action.kind==='Open menu') lines.push({kind:'system',text:'§e[Menu] §fWould open menu: §b'+(action.detail||'')})
  else if(action.kind==='Close menu') lines.push({kind:'system',text:'§e[Menu] §fWould close this inventory.'})
  else if(action.kind==='Play sound') lines.push({kind:'system',text:'§7[Preview] §fWould play sound: §b'+action.detail})
  else if(action.kind==='Connect server') lines.push({kind:'system',text:'§7[Preview] §fWould connect to: §b'+action.detail})
  else if(action.kind==='Refresh menu') lines.push({kind:'system',text:'§7[Menu] §fWould refresh this inventory.'})
  else lines.push({kind:'system',text:'§7[Preview] §f'+(action.detail||action.raw)})
 })
 return lines
}

