 const [showMenuPreview,setShowMenuPreview]=useState(false),[previewClosing,setPreviewClosing]=useState(false),[previewStyle,setPreviewStyle]=useState(()=>safeGet('deluxestudio-preview-style')||'chest'),[previewDuration,setPreviewDuration]=useState(()=>Number(safeGet('deluxestudio-preview-duration')||420)),[previewEasing,setPreviewEasing]=useState(()=>safeGet('deluxestudio-preview-easing')||'cubic-bezier(.2,.8,.2,1)'),[previewStagger,setPreviewStagger]=useState(()=>safeGet('deluxestudio-preview-stagger')!=='false'),[previewReducedMotion,setPreviewReducedMotion]=useState(()=>safeGet('deluxestudio-preview-reduced')==='true')
