 const previewActions=getPreviewActions(previewSelectedItem,previewClickType)
 useEffect(()=>{safeSet('deluxestudio-project',yaml)},[yaml])
 useEffect(()=>{setRawMenuText(yaml)},[yaml])
 useEffect(()=>{setProjectFiles(files=>files.map(file=>file.id===activeFile?{...file,yaml}:file))},[yaml,activeFile])
 useEffect(()=>{safeSet('deluxestudio-project-files',JSON.stringify(projectFiles));safeSet('deluxestudio-active-file',activeFile)},[projectFiles,activeFile])
 useEffect(()=>{safeSet('deluxestudio-preview-style',previewStyle);safeSet('deluxestudio-preview-duration',String(previewDuration));safeSet('deluxestudio-preview-easing',previewEasing);safeSet('deluxestudio-preview-stagger',String(previewStagger));safeSet('deluxestudio-preview-reduced',String(previewReducedMotion))},[previewStyle,previewDuration,previewEasing,previewStagger,previewReducedMotion])
 useEffect(()=>{const handleTool=e=>setActiveTool(e.detail);window.addEventListener('deluxestudio-tool',handleTool);return()=>window.removeEventListener('deluxestudio-tool',handleTool)},[])
